from qiskit import QuantumCircuit, QuantumRegister 

class BernsteinVaziraniV1(QuantumCircuit):





    def __init__(self, secret: str, insert_barriers: bool = False, name: str | None = None):










        if not secret or any(c not in "01" for c in secret):
            raise ValueError("secret must be a non-empty binary string")

        self._secret = secret
        self._n = len(secret)
        self._insert_barriers = insert_barriers


        q_input = QuantumRegister(self._n, "q")
        q_aux = QuantumRegister(1, "aux")

        super().__init__(q_input, q_aux, name=name or "BV")
        self._build()

        if self.num_qubits > 0:
            self.x(0)                                                            


    def _build(self) -> None:
        n = self._n


        self.h(n)
        self.z(n)


        for i in range(n):
            self.h(i)


        if self._insert_barriers:
            self.barrier()


        s = self._secret[::-1]                                           
        for q in range(n):
            if s[q] == '0':
                self.id(q)
            else:
                self.cx(q, n)


        if self._insert_barriers:
            self.barrier()


        for i in range(n):
            self.h(i)

