from typing import List, Optional, Union
import numpy

from qiskit.circuit import QuantumCircuit, AncillaQubit
from qiskit.exceptions import QiskitError
from qiskit.quantum_info import Statevector, Operator, DensityMatrix
from qiskit.utils.deprecation import deprecate_func
from qiskit.circuit.library import MCXGate                                                    

import numpy as np

from qolumbina.programs.diagonal import Diagonal

class GroverOperatorV1(QuantumCircuit):


    def __init__(
        self,
        oracle: QuantumCircuit | Statevector,
        state_preparation: QuantumCircuit | None = None,
        zero_reflection: QuantumCircuit | DensityMatrix | Operator | None = None,
        reflection_qubits: list[int] | None = None,
        insert_barriers: bool = False,
        name: str = "Q",
    ):
















        super().__init__(name=name)


        self._oracle = oracle
        self._reflection_qubits = reflection_qubits
        self._state_preparation = state_preparation
        self._insert_barriers = insert_barriers
        self._zero_reflection = zero_reflection
        self.name = name


        self._build()

        if self.num_qubits > 0:
            self.x(0)                                                            

    def _build(self) -> None:

        if isinstance(self._oracle, QuantumCircuit):
            circuit = self._oracle.copy_empty_like(name=self.name, vars_mode="drop")
        else:
            circuit = QuantumCircuit(self._oracle.num_qubits, name=self.name)






        if isinstance(self._oracle, Statevector):
            diagonal = Diagonal((-1) ** self._oracle.data)               
            circuit.compose(diagonal, inplace=True)
        else:
            circuit.compose(self._oracle, inplace=True)
        if self._insert_barriers:
            circuit.barrier()





        if self._reflection_qubits is None:
            self.reflection_qubits = [
                i for i, qubit in enumerate(circuit.qubits) if not isinstance(qubit, AncillaQubit)
            ]


        if self._state_preparation is None:
            circuit.h(self.reflection_qubits)                     
        else:
            circuit.compose(self._state_preparation.inverse(), inplace=True)

        if self._insert_barriers:
            circuit.barrier()


        if self._zero_reflection is None:
            num_reflection = len(self.reflection_qubits)

            circuit.x(self.reflection_qubits)
            if num_reflection == 1:
                circuit.z(
                    self.reflection_qubits[0]
                )                                                           
            else:
                mcx = MCXGate(num_reflection - 1)

                circuit.h(self.reflection_qubits[-1])
                circuit.append(mcx, self.reflection_qubits)
                circuit.h(self.reflection_qubits[-1])
            circuit.x(self.reflection_qubits)

        elif isinstance(self._zero_reflection, (Operator, DensityMatrix)):
            diagonal = Diagonal(self._zero_reflection.data.diagonal())               
            circuit.compose(diagonal, inplace=True)

        else:
            circuit.compose(self._zero_reflection, inplace=True)

        if self._insert_barriers:
            circuit.barrier()


        if self._state_preparation is None:
            circuit.h(self.reflection_qubits)
        else:
            circuit.compose(self._state_preparation, inplace=True)


        circuit.global_phase = numpy.pi


        self.add_register(*circuit.qregs)
        self.compose(circuit, inplace=True)
