from qiskit import QuantumCircuit, QuantumRegister, ClassicalRegister

from typing import List


class HiddenShiftV1(QuantumCircuit):
    f"""
    Hidden Shift Benchmark Program Circuit:
    """

    def __init__(
        self, 
        hidden_bits: list[int], 
        if_barrier: bool = True,
        name: str | None = None
    ):











        self._hidden_bits = hidden_bits
        self._num_qubits = len(hidden_bits)
        self._if_barrier = if_barrier

        if self._num_qubits % 2 != 0:
            raise ValueError(
                f"The number of qubits must be even ({self._num_qubits});"
                f"otherwise, the bent function is not achievable.")

        super().__init__(self._num_qubits, name=name or f"HiddenShift")


        self._build()

        if self.num_qubits > 0:
            self.x(0)                                                            


    def Uf_oracle(self, num_qubits: int, hidden_bits: list[int]) -> QuantumCircuit:










        qr = QuantumRegister(num_qubits)
        qc = QuantumCircuit(qr, name="Uf")



        for i_qubit in range(num_qubits):
            if hidden_bits[i_qubit]==1:
                qc.x(qr[i_qubit])

        for i_qubit in range(0,num_qubits-1,2):
            qc.cz(qr[i_qubit], qr[i_qubit+1])



        for i_qubit in range(num_qubits):
            if hidden_bits[i_qubit]==1:
                qc.x(qr[i_qubit])

        return qc

    def Ug_oracle(self, num_qubits: int) -> QuantumCircuit:








        qr = QuantumRegister(num_qubits)
        qc = QuantumCircuit(qr, name="Ug")

        for i_qubit in range(0,num_qubits-1,2):
            qc.cz(qr[i_qubit], qr[i_qubit+1])

        return qc

    def _build(self) -> None:
        num_qubits = self._num_qubits
        hidden_bits = self._hidden_bits


        qr = QuantumRegister(num_qubits)
        qc = QuantumCircuit(qr)


        for i_qubit in range(num_qubits):
            qc.h(qr[i_qubit])

        if self._if_barrier:
            qc.barrier()


        Uf = self.Uf_oracle(num_qubits, hidden_bits)
        qc.append(Uf,qr)

        if self._if_barrier:
            qc.barrier()


        for i_qubit in range(num_qubits):
            qc.h(qr[i_qubit])

        if self._if_barrier:
            qc.barrier()


        Ug = self.Ug_oracle(num_qubits)
        qc.append(Ug,qr)

        if self._if_barrier:
            qc.barrier()


        for i_qubit in range(num_qubits):
            qc.h(qr[i_qubit])

        if self._if_barrier:
            qc.barrier()


        qc2 = qc.decompose()

        self.compose(qc2, inplace=True)


