import numpy as np

from qiskit.circuit.quantumcircuit import QuantumCircuit
from qiskit.circuit import QuantumRegister
from qiskit.circuit.library.standard_gates import PhaseGate
from qolumbina.programs.quantum_fourier_transform import QFT

class MultiplierQFTV1(QuantumCircuit):



























    def __init__(
        self,
        num_state_qubits: int,
        num_result_qubits: int | None = None,
        label: str | None = None,
    ) -> None:













        if num_state_qubits < 1:
            raise ValueError("The number of state qubits must be at least 1.")

        if num_result_qubits is None:
            num_result_qubits = 2 * num_state_qubits
        elif num_result_qubits < num_state_qubits or num_result_qubits > 2 * num_state_qubits:
            raise ValueError(
                f"num_result_qubits ({num_result_qubits}) must be in between num_state_qubits "
                f"({num_state_qubits}) and 2 * num_state_qubits ({2 * num_state_qubits})"
            )


        super().__init__(
            2 * num_state_qubits + num_result_qubits,
            name="Multiplier" or label
        )                               

        self._num_state_qubits = num_state_qubits
        self._num_result_qubits = num_result_qubits


        self._build()

        if self.num_qubits > 0:
            self.x(0)                                                            

    @property
    def num_state_qubits(self) -> int:





        return self._num_state_qubits

    @property
    def num_result_qubits(self) -> int:





        return self._num_result_qubits


    def _multiplier_qft_r17(
        self, num_state_qubits: int, num_result_qubits: int | None = None
    ) -> QuantumCircuit:








































        if num_result_qubits is None:
            num_result_qubits = 2 * num_state_qubits
        elif num_result_qubits < num_state_qubits or num_result_qubits > 2 * num_state_qubits:
            raise ValueError(
                f"num_result_qubits ({num_result_qubits}) must be in between num_state_qubits "
                f"({num_state_qubits}) and 2 * num_state_qubits ({2 * num_state_qubits})"
            )

        qr_a = QuantumRegister(num_state_qubits, name="a")
        qr_b = QuantumRegister(num_state_qubits, name="b")
        qr_out = QuantumRegister(num_result_qubits, name="out")


        circuit = QuantumCircuit(qr_a, qr_b, qr_out)



        qft = QFT(num_result_qubits).to_gate()

        circuit.append(qft, qr_out[:])

        for j in range(1, num_state_qubits + 1):
            for i in range(1, num_state_qubits + 1):
                for k in range(1, num_result_qubits + 1):
                    lam = (2 * np.pi) / (2 ** (i + j + k - 2 * num_state_qubits))



                    circuit.append(
                        PhaseGate(lam).control(2, annotated=False),
                        [qr_a[num_state_qubits - j], qr_b[num_state_qubits - i], qr_out[~(k - 1)]],
                    )

        circuit.append(qft.inverse(), qr_out[:])

        return circuit

    def _build(self):








        sub_circuit = self._multiplier_qft_r17(self.num_state_qubits)                  
        self.compose(sub_circuit.to_gate(), inplace=True)
